def merge_intervals(spans):
    # sort by start, then fold: extend the tail or push a new span
    out = []
    for start, end in sorted(spans):
        if out and start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out


def total_covered(spans):
    return sum(end - start for start, end in merge_intervals(spans))


if __name__ == "__main__":
    demo = [(1, 3), (2, 8), (7, 9), (10, 14)]
    print(merge_intervals(demo))
    print(total_covered(demo))
